<script setup>
import { computed, ref } from 'vue'
import { Wallet, ArrowUpRight, ArrowRight, CheckCheck, UsersRound, ChartNoAxesCombined, Plus, QrCode, CalendarDays, Heart, ChevronDown } from 'lucide-vue-next'
import { useAppStore } from '../stores/app'
import { money, initials, localDate } from '../utils/format'
import StatCard from '../components/StatCard.vue'
import TipsChart from '../components/TipsChart.vue'
import PaymentTable from '../components/PaymentTable.vue'
const store = useAppStore(), days = ref(7)
const leaders = computed(() => store.employees.map(e => ({ ...e, sum: store.successful.filter(p=>p.employeeId===e.id).reduce((s,p)=>s+p.amount,0) })).sort((a,b)=>b.sum-a.sum).slice(0,3))
const periodPayments = computed(() => { const start=new Date(); start.setDate(start.getDate()-days.value+1); return store.payments.filter(p=>localDate(p.createdAt)>=localDate(start)) })
const periodTotal = computed(()=>periodPayments.value.filter(p=>p.status==='success').reduce((s,p)=>s+p.amount,0))
</script>
<template><div class="page-heading"><div><div class="eyebrow">ВАШ РЕСТОРАН В ЦИФРАХ</div><h1>Обзор <span class="heading-dot">.</span></h1><p>Хороший сервис заслуживает благодарности.</p></div><RouterLink to="/app/qr" class="btn btn-primary"><Plus :size="18" />Создать QR-код</RouterLink></div><div class="welcome-banner"><div class="welcome-icon"><Heart :size="26" /></div><div><strong>Маленькое «спасибо». Большая мотивация.</strong><p>Принимайте чаевые по QR-коду — заботьтесь о тех, кто заботится о гостях.</p></div><RouterLink to="/app/employees" class="banner-link">Добавить команду<ArrowUpRight :size="17" /></RouterLink><div class="banner-decoration">✳</div></div><div class="stats-grid"><StatCard label="Всего чаевых" :value="money(store.total)" note="За всё время · успешные платежи" :icon="Wallet" accent/><StatCard label="Успешные платежи" :value="store.successful.length" note="Каждый платёж — чьё-то спасибо" :icon="CheckCheck"/><StatCard label="Средние чаевые" :value="money(store.average)" note="В среднем за один платёж" :icon="ChartNoAxesCombined"/><StatCard label="Сотрудники" :value="store.employees.filter(e=>e.active).length" :note="`${store.employees.length} в команде всего`" :icon="UsersRound"/></div><div v-if="store.payments.length" class="overview-middle"><section class="panel chart-panel"><div class="panel-heading"><div><h2>Динамика чаевых</h2><p>Благодарность, которую видно</p></div><label class="select-compact"><CalendarDays :size="15"/><select v-model.number="days" aria-label="Период графика"><option :value="7">7 дней</option><option :value="14">14 дней</option><option :value="30">30 дней</option></select></label></div><div class="chart-summary"><strong>{{ money(periodTotal) }}</strong><span>за {{ days }} дней</span><span class="legend"><i></i>Чаевые</span></div><TipsChart :payments="periodPayments" :days="days" /></section><section class="panel leaders-panel"><div class="panel-heading"><div><h2>Команда в деле</h2><p>Лидеры по чаевым за всё время</p></div><UsersRound :size="19" class="muted" /></div><div v-if="!leaders.length" class="empty compact">Добавьте первого сотрудника</div><div v-for="(e,i) in leaders" :key="e.id" class="leader"><span class="leader-rank">0{{ i+1 }}</span><span class="avatar" :class="e.color">{{ initials(e.name) }}</span><div class="leader-name"><strong>{{ e.name }}</strong><span>{{ e.role }}</span></div><strong>{{ money(e.sum) }}</strong></div><RouterLink to="/app/employees" class="text-link leader-link">Вся команда<ArrowRight :size="16" /></RouterLink></section></div><section v-if="store.payments.length" class="panel"><div class="panel-heading"><div><h2>Последние платежи</h2><p>Новые «спасибо» от ваших гостей</p></div><RouterLink to="/app/payments" class="text-link">Все платежи<ArrowRight :size="16" /></RouterLink></div><PaymentTable :payments="store.sortedPayments.slice(0,5)" :employee-name="store.employeeName" /></section><section v-else class="panel empty account-empty"><UsersRound :size="36"/><h3>Здесь начинается история вашего ресторана</h3><p>Пока нет платежей. Добавьте сотрудника и создайте QR-код, чтобы принять первые чаевые.</p><RouterLink :to="store.employees.length ? '/app/qr' : '/app/employees'" class="btn btn-primary"><Plus :size="17"/>{{ store.employees.length ? 'Создать первый QR-код' : 'Добавить первого сотрудника' }}</RouterLink></section><div class="bottom-note"><span class="live-dot"></span>Данные сохраняются автоматически в этом браузере<span>Сделано с заботой о вашей команде <Heart :size="13" /></span></div></template>
